// The Videos page reads this split (longform 16:9 vs Shorts 9:16) — generated by
// tools/site_videos.py (YouTube Data API + /shorts classification) and refreshed on a
// schedule (refresh-videos.yml). Static import => the build never depends on the network.

import data from "../data/videos.json";

export const CHANNEL_URL = "https://www.youtube.com/@Kiwinoy";
export const CHANNEL_HANDLE = "Kiwinoy";
export const longform = data.longform || [];
export const shorts = data.shorts || [];
export const counts = data.counts || { longform: longform.length, shorts: shorts.length };
